const unsaveRepo = `-- name: UnsaveRepo :execrows
DELETE FROM "SavedRepo"
WHERE "userId" = $1 AND "repositoryId" = $2
`

type UnsaveRepoParams struct {
	UserId       string `db:"userId" json:"userId"`
	RepositoryId string `db:"repositoryId" json:"repositoryId"`
}

func (q *Queries) UnsaveRepo(ctx context.Context, arg UnsaveRepoParams) (int64, error) {
	result, err := q.db.Exec(ctx, unsaveRepo, arg.UserId, arg.RepositoryId)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

